import React from 'react';
import { MedicalIncidentStats } from '../../../models/MedicalIncident';
import { StatsCardsGrid, StatsCard } from '@linm-soft-org/linm-web-common-components';

interface Props {
  stats: MedicalIncidentStats;
  loading?: boolean;
  /** Currently active stats-card filter key. 'all' = no filter. */
  activeFilter?: string;
  /** Called when user clicks a card. Key matches IncidentStatus value or 'all' / 'severe'. */
  onFilter?: (key: string) => void;
}

export const MedicalIncidentStatsCards: React.FC<Props> = ({
  stats,
  loading,
  activeFilter = 'all',
  onFilter,
}) => {
  const handleClick = (key: string) => {
    if (!onFilter) return;
    // Toggle off when clicking the already-active card → revert to 'all'
    onFilter(activeFilter === key ? 'all' : key);
  };

  return (
    <StatsCardsGrid>
      <StatsCard
        label="Tổng sự cố"
        value={stats.total}
        icon="fas fa-clipboard-list"
        variant="primary"
        loading={loading}
        active={activeFilter === 'all'}
        onClick={() => handleClick('all')}
      />
      <StatsCard
        label="Nhầm sự cố"
        value={stats.notMedicalIncidentCount ?? 0}
        icon="fas fa-ban"
        variant="gray"
        loading={loading}
        active={activeFilter === 'notMedicalIncident'}
        onClick={() => handleClick('notMedicalIncident')}
      />
      <StatsCard
        label="Nháp"
        value={stats.draft}
        icon="fas fa-pencil-alt"
        variant="gray"
        loading={loading}
        active={activeFilter === 'draft'}
        onClick={() => handleClick('draft')}
      />
      <StatsCard
        label="Đã gửi"
        value={stats.submitted}
        icon="fas fa-paper-plane"
        variant="info"
        loading={loading}
        active={activeFilter === 'submitted'}
        onClick={() => handleClick('submitted')}
      />
      <StatsCard
        label="Đang phân tích"
        value={stats.inAnalysis}
        icon="fas fa-search"
        variant="warning"
        loading={loading}
        active={activeFilter === 'in_analysis'}
        onClick={() => handleClick('in_analysis')}
      />
      <StatsCard
        label="Đã hoàn thành"
        value={stats.resolved}
        icon="fas fa-check-circle"
        variant="success"
        loading={loading}
        active={activeFilter === 'resolved'}
        onClick={() => handleClick('resolved')}
      />
      <StatsCard
        label="Nghiêm trọng"
        value={stats.severeCount}
        icon="fas fa-exclamation-circle"
        variant="danger"
        loading={loading}
        active={activeFilter === 'severe'}
        onClick={() => handleClick('severe')}
      />
    </StatsCardsGrid>
  );
};
