import React, { useEffect, useMemo, useState } from 'react';
import {
  MedicalIncidentFilters,
  IncidentSeverity,
  IncidentReportType,
  IncidentListStatusFilter,
} from '../../../models/MedicalIncident';
import { useFormOptions } from '../../../hooks/useFormOptions';
import { buildIncidentListStatusOptions } from '../../../utils/incidentListStatusFilter';
import styles from './MedicalIncidentFiltersBar.module.css';
import {
  LinErpListFilterBar,
  SearchTextInput,
  Select,
  SelectOption,
} from '@linm-soft-org/linm-web-common-components';

const TEST_ID_PREFIX = 'medical-incidents-list';

interface Props {
  filters: MedicalIncidentFilters;
  onChange: (f: MedicalIncidentFilters) => void;
  onClear: () => void;
  loading?: boolean;
}

export const MedicalIncidentFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
  loading = false,
}) => {
  const [draft, setDraft] = useState<MedicalIncidentFilters>(filters);

  const {
    departmentOptions,
    incidentStatusOptions,
    incidentSeverityOptions,
    incidentReportTypeOptions,
  } = useFormOptions('incident-list');

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  const allStatusOptions: SelectOption[] = useMemo(
    () => buildIncidentListStatusOptions(incidentStatusOptions),
    [incidentStatusOptions],
  );

  const allSeverityOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả mức độ' }, ...incidentSeverityOptions],
    [incidentSeverityOptions],
  );

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa báo cáo' }, ...departmentOptions],
    [departmentOptions],
  );

  const allReportTypeOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả hình thức' }, ...incidentReportTypeOptions],
    [incidentReportTypeOptions],
  );

  const hasActiveFilters = useMemo(() => {
    return !!(
      draft.search ||
      draft.status ||
      draft.severity ||
      draft.reportingDepartmentId ||
      draft.reportType ||
      draft.dateFrom ||
      draft.dateTo
    );
  }, [draft]);

  const handleSearch = () => {
    onChange({
      ...draft,
      search: draft.search?.trim() || undefined,
      status: draft.status || undefined,
      severity: draft.severity || undefined,
      reportingDepartmentId: draft.reportingDepartmentId || undefined,
      reportType: draft.reportType || undefined,
    });
  };

  const handleClear = () => {
    setDraft({});
    onClear();
  };

  return (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID_PREFIX}
      fromDate={draft.dateFrom}
      toDate={draft.dateTo}
      onDateChange={(fromDate, toDate) => {
        const next = { ...draft, dateFrom: fromDate, dateTo: toDate };
        setDraft(next);
        onChange({
          ...filters,
          dateFrom: fromDate,
          dateTo: toDate,
        });
      }}
      onSearch={handleSearch}
      loading={loading}
      leading={(
        <>
          <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
            <SearchTextInput
              placeholder="Tìm kiếm mã, tên sự cố, bệnh nhân..."
              value={draft.search ?? ''}
              onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
              onSearch={handleSearch}
              testId={`${TEST_ID_PREFIX}-search-text`}
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-status`}>
            <Select
              options={allStatusOptions}
              value={draft.status ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  status: e.target.value as IncidentListStatusFilter,
                }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-severity`}>
            <Select
              options={allSeverityOptions}
              value={draft.severity ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  severity: e.target.value as IncidentSeverity | '',
                }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-reportingDepartment`}>
            <Select
              label="Khoa báo cáo"
              options={allDeptOptions}
              value={draft.reportingDepartmentId ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({ ...prev, reportingDepartmentId: e.target.value }))
              }
              size="small"
            />
          </div>
          <div data-testid={`${TEST_ID_PREFIX}-field-reportType`}>
            <Select
              options={allReportTypeOptions}
              value={draft.reportType ?? ''}
              onChange={(e) =>
                setDraft((prev) => ({
                  ...prev,
                  reportType: e.target.value as IncidentReportType | '',
                }))
              }
              size="small"
            />
          </div>
          {hasActiveFilters && (
            <button
              className={styles.clearFiltersButton}
              onClick={handleClear}
              type="button"
              title="Xóa bộ lọc"
            >
              <i className="fas fa-times-circle" />
              <span>Xóa bộ lọc</span>
            </button>
          )}
        </>
      )}
    />
  );
};
